#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

/**
 * Problem: 22261 - Sorting the alphanumeric list in comma separated value format
 * 
 * 解題思路：
 * 1. 讀取 CSV 格式的資料，每一行包含多個以逗號分隔的欄位。
 * 2. 排序規則：
 *    - 依序比較各個欄位。
 *    - 比較時忽略欄位的前導和結尾空格。
 *    - 如果欄位內容完全相同，則維持原始順序（穩定排序）。
 * 3. 輸出時必須保留原始的所有空格。
 * 4. 實作細節：
 *    - 使用結構存儲原始行、原始欄位列表以及去空格後的欄位列表。
 *    - 自定義比較函式進行排序。
 */

string trim(const string& s) {
    size_t first = s.find_first_not_of(' ');
    if (first == string::npos) return "";
    size_t last = s.find_last_not_of(' ');
    return s.substr(first, last - first + 1);
}

struct Row {
    string original_line;
    vector<string> trimmed_fields;
    int original_index;
};

bool compareRows(const Row& a, const Row& b) {
    int n = min((int)a.trimmed_fields.size(), (int)b.trimmed_fields.size());
    for (int i = 0; i < n; i++) {
        if (a.trimmed_fields[i] != b.trimmed_fields[i])
            return a.trimmed_fields[i] < b.trimmed_fields[i];
    }
    if (a.trimmed_fields.size() != b.trimmed_fields.size())
        return a.trimmed_fields.size() < b.trimmed_fields.size();
    return a.original_index < b.original_index;
}

void solve() {
    string line;
    vector<Row> rows;
    int idx = 0;
    while (getline(cin, line) && !line.empty()) {
        Row row;
        row.original_line = line;
        row.original_index = idx++;
        stringstream ss(line);
        string field;
        while (getline(ss, field, ',')) {
            row.trimmed_fields.push_back(trim(field));
        }
        rows.push_back(row);
    }

    sort(rows.begin(), rows.end(), compareRows);

    for (const auto& row : rows) {
        cout << row.original_line << endl;
    }
}

int main() {
    int n;
    if (cin >> n) {
        string dummy;
        getline(cin, dummy); // consume newline
        while (n--) {
            getline(cin, dummy); // consume empty line
            solve();
            if (n > 0) cout << endl;
        }
    }
    return 0;
}
